def oracle(text):
    tokens = [int(value) for value in text.split()]
    case_count = tokens[4096]
    cursor = 4097
    answers = []
    for _ in range(case_count):
        bus_count = tokens[cursor]
        bus_capacity = tokens[cursor + 1]
        cursor += 2
        total_size = bus_count * bus_capacity
        total = 0
        for divisor in range(1, total_size + 1):
            if total_size % divisor == 0:
                group_count = total_size // divisor
                total += math.factorial(total_size) // (math.factorial(divisor) ** group_count * math.factorial(group_count))
        answers.append(str(total % MOD))
    return "\n".join(answers) + "\n"


def write(name, pairs):
    text = "\n".join(str(value) for value in FACTORIAL_TABLE) + "\n"
    text += str(len(pairs)) + "\n"
    text += "".join(f"{buses} {capacity}\n" for buses, capacity in pairs)
    (ROOT / "in" / f"{name}.txt").write_text(text)
    (ROOT / "out" / f"{name}.out").write_text(oracle(text))


SAMPLE = [(2, 2), (1, 6), (2, 3)]
def sample_text():
    text = "\n".join(str(value) for value in FACTORIAL_TABLE) + "\n3\n"
    text += "".join(f"{buses} {capacity}\n" for buses, capacity in SAMPLE)
    return text
assert oracle(sample_text()) == "5\n27\n27\n"
assert FACTORIAL_TABLE[0] == 1
assert FACTORIAL_TABLE[1] == 639926614
assert FACTORIAL_TABLE[-1] == 0
assert math.factorial(6) // (math.factorial(3) ** 2 * 2) % MOD == 10


def build():
    write("2_edges", [(1, 1), (2, 1), (1, 2), (3, 2), (1, 10), (5, 5)])
    write("3_wide", [(100, 10), (50, 20), (25, 40), (10, 100)])
    rng = random.Random(20261126)
    write("4_random", [(rng.randint(1, 60), rng.randint(1, 30)) for _ in range(12)])
    write("5_io", [(rng.randint(40, 80), rng.randint(10, 25)) for _ in range(20)])


(ROOT / "in").mkdir(exist_ok=True)
(ROOT / "out").mkdir(exist_ok=True)
write("1_sample", SAMPLE)
build()
